public class ConcentricRingPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int size, int rings, java.awt.Color[] colors) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                size, size, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            ConcentricRingPainter.paint(g, size, rings, colors);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.Color[] four = { java.awt.Color.RED, java.awt.Color.GREEN, java.awt.Color.BLUE, java.awt.Color.YELLOW };
            java.awt.image.BufferedImage a = render(80, 4, four);
            java.awt.Color[] two = { java.awt.Color.BLACK, java.awt.Color.WHITE };
            java.awt.image.BufferedImage b = render(60, 3, two);
            check("innermost ring at centre (40,40)", "#FFFF00", pixel(a, 40, 40));
            check("third ring at (40,25)", "#0000FF", pixel(a, 40, 25));
            check("second ring at (40,15)", "#00FF00", pixel(a, 40, 15));
            check("outer ring at (40,5)", "#FF0000", pixel(a, 40, 5));
            check("background corner (3,3)", "#FFFFFF", pixel(a, 3, 3));
            check("palette wraps: centre of 3 rings (30,30)", "#000000", pixel(b, 30, 30));
            check("middle ring (30,15)", "#FFFFFF", pixel(b, 30, 15));
            check("outer ring (30,5)", "#000000", pixel(b, 30, 5));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

